import sqlite3

app = Flask(__name__)

class QueryBuilder:
    @staticmethod
    def build_set_clause(fields):
        # Masking: The vulnerability is buried in a static method string join
        return ", ".join([f"{k} = ?" for k in fields.keys()])

@app.route('/api/user/sync', methods=['POST'])
def sync_user():
    user_data = request.json  # e.g., {"bio": "hello", "user_id": 1}
    target_id = user_data.pop('user_id')

    # Bandit often misses vulnerabilities when column names are generated from dict keys
    set_clause = QueryBuilder.build_set_clause(user_data)

    conn = sqlite3.connect('users.db')
    sql = f"UPDATE users SET {set_clause} WHERE id = ?"

    # Values are parameterized, but keys (columns) are injected
    conn.execute(sql, (*user_data.values(), target_id))
    conn.commit()
    return {"status": "success"}

