from flask import Flask, request, abort
import sqlite3

app = Flask(__name__)
ALLOWED_COLUMNS = {'bio', 'display_name', 'timezone'}

@app.route('/api/user/sync', methods=['POST'])
def sync_user():
    user_data = request.json
    if not all(k in ALLOWED_COLUMNS for k in user_data.keys() if k != 'user_id'):
        abort(400)

    target_id = user_data.pop('user_id')
    set_clause = ", ".join([f"{k} = ?" for k in user_data.keys()])

    conn = sqlite3.connect('users.db')
    sql = f"UPDATE users SET {set_clause} WHERE id = ?"
    conn.execute(sql, (*user_data.values(), target_id))
    conn.commit()
    return {"status": "success"}

